sys_script.script:
(function executeRule(current, previous) {
    var studentName = current.getValue('student_name');
    if (!studentName) {
        return;
    }

    // Check if user is already set
    if (current.getValue('user')) {
        return;
    }

    // Search sys_user by name
    var userGr = new GlideRecord('sys_user');
    userGr.addQuery('name', studentName);
    userGr.query();

    if (userGr.next()) {
        // User exists - link it
        current.setValue('user', userGr.getUniqueValue());
    } else {
        // Create new sys_user
        var newUser = new GlideRecord('sys_user');
        newUser.initialize();
        newUser.setValue('first_name', studentName.split(' ')[0] || studentName);
        var lastNameParts = studentName.split(' ');
        lastNameParts.shift();
        newUser.setValue('last_name', lastNameParts.join(' ') || '');
        newUser.setValue('name', studentName);

        var studentId = current.getValue('student_id_number');
        newUser.setValue('user_name', studentId ? studentId.toLowerCase() : studentName.toLowerCase().replace(/\s+/g, '.'));
        newUser.setValue('employee_number', studentId || '');

        var college = current.getValue('college_name');
        if (college) {
            newUser.setValue('company', college);
        }

        var userId = newUser.insert();
        if (userId) {
            current.setValue('user', userId);
        }
    }
})(current, previous);
